import numpy as np

def sphere(x):
    """Sphere function: f(x) = Sum(x^2)"""
    return np.sum(x**2)


def rastrigin(x):
    """Rastrigin function: f(x) = 10n + sum(x^2 - 10*cos(2*pi*x))"""
    n = len(x)
    return 10 * n + np.sum(x**2 - 10 * np.cos(2 * np.pi * x))


def quadratic(x):
    """Quadratic function: f(x) = (x-3)^2"""
    if isinstance(x, np.ndarray):
        return np.sum((x - 3)**2)
    else:
        return (x - 3)**2


def oscillating(x):
    """Oscillating function: f(x) = x^2 + 10(1 - cos(2*pi*x))"""
    if isinstance(x, np.ndarray):
        return np.sum(x**2 + 10 * (1 - np.cos(2 * np.pi * x)))
    else:
        return x**2 + 10 * (1 - np.cos(2 * np.pi * x))


def multi_modal(x):
    """Multi-modal function: f(x) = x^4 - 3x^3 + 2"""
    if isinstance(x, np.ndarray):
        return np.sum(x**4 - 3*x**3 + 2)
    else:
        return x**4 - 3*x**3 + 2


def lab6_custom(x):
    """Lab 6 custom: f(x) = 10n + Sum((x-2)^2 - 10cos(2*pi*(x-2)))"""
    n = len(x)
    return 10 * n + np.sum((x - 2)**2 - 10 * np.cos(2 * np.pi * (x - 2)))
